const logisticsDefaults={hotel:{name:'南浦站步行 5–10 分鐘內的飯店（待訂）',night:90000,rooms:1,people:2,nights:3},transport:[[{time:'09:30',name:'金海機場 → 南浦洞住宿',note:'機場輕軌 → 沙上轉地鐵 2 號線 → 西面轉 1 號線 → 南浦。預留 75–100 分鐘；行李先寄放，入住依飯店規定。',cost:5000},{time:'13:00',name:'南浦洞 → 甘川文化村 → 札嘎其',note:'地鐵 1 號線至土城，轉當地公車或計程車上山；返程往札嘎其。每段預留 30–45 分鐘；回南浦商圈可步行。',cost:7000}],[{time:'09:00',name:'南浦 → 海雲台',note:'地鐵 1 號線至西面，轉 2 號線至海雲台，步行到海灘。預留 70–90 分鐘。',cost:3000},{time:'16:00',name:'海雲台 → 廣安里 → 南浦',note:'2 號線至金蓮山或廣安站，步行至海灘；返程經西面轉 1 號線。去程約 35–50 分鐘，回程約 60–80 分鐘。',cost:5000}],[{time:'08:30',name:'南浦 → 海東龍宮寺 → 南浦',note:'1 號線至西面轉 2 號線往海雲台，再搭往龍宮寺方向公車；以 Naver Map 當日建議為準。單程預留 110–140 分鐘，轉乘多，當天不排滿。',cost:10000}],[{time:'12:00',name:'南浦 → 金海機場',note:'1 號線至西面 → 2 號線至沙上 → 輕軌至機場。預留 75–100 分鐘交通，另依航空公司要求提早抵達；以 17:00 國際航班示例，12:00 出發保留緩衝。',cost:5000}]],meals:[[{time:'12:00',name:'南浦洞豬肉湯飯午餐',note:'在南浦／札嘎其一帶找豬肉湯飯店；不吃豬肉可換蔬菜拌飯並詢問高湯成分。',cost:12000},{time:'18:30',name:'札嘎其海鮮晚餐＋BIFF 小吃',note:'海鮮先確認重量、料理費與總價；BIFF 可嘗試種子糖餅。海鮮與堅果過敏者需改餐。',cost:30000}],[{time:'08:00',name:'住宿附近早餐',note:'便利商店或麵包店簡單吃，預留水與隨身點心。',cost:7000},{time:'12:30',name:'海雲台小麥冷麵午餐',note:'海雲台商圈找小麥冷麵；怕冷可改湯飯，依店家菜單選擇。',cost:12000},{time:'18:30',name:'廣安里晚餐與海邊咖啡',note:'先用晚餐，再找能看海的咖啡館。預算包含餐點與一杯飲料。',cost:25000}],[{time:'07:30',name:'早餐後再出發',note:'龍宮寺單程較遠，先在住宿附近吃早餐。',cost:7000},{time:'12:30',name:'機張／松亭午餐',note:'挑寺院回程路線附近的韓式定食或麵食，避免為用餐特別繞路。',cost:15000},{time:'18:30',name:'南浦洞韓式家常晚餐',note:'回住宿周邊吃定食，保留晚上整理行李的時間。',cost:18000}],[{time:'08:30',name:'慢慢吃早餐',note:'住宿附近早餐，回房檢查行李後退房。',cost:7000},{time:'11:00',name:'南浦洞午餐',note:'午餐後取行李出發去機場；若航班更早，刪除此餐並提早出發。',cost:12000}]]};
