const coordinates={gamcheon:[35.0975,129.0106],jagalchi:[35.0967,129.0306],biff:[35.0984,129.0282],haeundae:[35.1587,129.1604],gwangalli:[35.1532,129.1187],yonggungsa:[35.1884,129.2233],hotel:[35.0979,129.0349],airport:[35.1796,128.9382]};
const routeSeeds=[['airport','hotel','gamcheon','jagalchi','biff','hotel'],['hotel','haeundae','gwangalli','hotel'],['hotel','yonggungsa','hotel'],['hotel','airport']];
const logisticsPanel=document.createElement('section');logisticsPanel.className='logistics-panel';logisticsPanel.innerHTML=`<div class="section-head"><div><div class="eyebrow">EVERY PART OF YOUR JOURNEY</div><h2>交通、食宿，一起安排好</h2></div></div><p class="planning-note">規劃假設：4 天 3 夜・2 人共住一間・南浦站住宿・首日 09:00 抵達、末日 17:00 起飛。時間與花費皆為規劃估算，並非即時報價。請依航班、住宿與體力調整。</p><div class="route-heading"><h3>每日路線地圖</h3><button class="text" id="map-full-route">開啟全日地圖 ↗</button></div><div id="route-map"></div><div id="map-status" class="muted"></div><p class="map-caption">虛線連接停留順序，非實際道路。住宿點以南浦站示意；自行新增且未定位的停留不顯示圖釘。</p><div id="route-stops"></div><div class="logistics-columns"><section><h3>⇄ 今日交通</h3><div id="transport-plan"></div></section><section><h3>♨ 今日餐食</h3><div id="meal-plan"></div></section></div><section class="hotel-plan"><div><small>YOUR HOME IN BUSAN</small><h3 id="hotel-name"></h3><p id="hotel-budget"></p><p>連住三晚可減少搬行李；優先選有電梯、可寄放行李且靠近地鐵的住宿。尚未預訂。</p><a class="text" href="https://map.naver.com/p/search/${encodeURIComponent('남포역 호텔')}" target="_blank" rel="noopener">查看南浦站附近住宿 ↗</a></div><button class="outline" id="edit-hotel">編輯住宿</button></section><div class="estimate-card"><h3>交通＋食宿預算試算</h3><div id="planning-budget"></div><p>每人估算；住宿依房數與人數分攤。包含餐食及交通預留，不含機票、門票、購物與保險。規劃預算與實際記帳分開計算。</p></div><div class="source-note">資料查核：<a href="https://www.airport.co.kr/gimhaeeng/cms/frCon/index.do?CONTENTS_NO=3&MENU_ID=110" target="_blank" rel="noopener">金海機場交通</a> · <a href="https://work.humetro.busan.kr/homepage/cht/page/subLocation.do?menu_no=100901040101" target="_blank" rel="noopener">釜山地鐵票價</a> · <a href="https://www.visitbusan.net/" target="_blank" rel="noopener">Visit Busan</a>。所有路段時間與食宿金額為本 App 自訂估算，出發前請查當日導航與店家報價。</div>`;
const routeView=document.createElement('section');routeView.id='route-view';routeView.hidden=true;routeView.innerHTML='<div class="greeting"><div><div class="eyebrow">ON THE GO, IN BUSAN</div><h1>路線與食宿</h1><p>今天怎麼走、吃什麼、住哪裡，一頁就好。</p></div></div><div id="route-tabs" class="day-tabs"></div>';routeView.append(logisticsPanel);$('footer').before(routeView);
let routeMap,routeLayers;function routeName(id){return id==='hotel'?'南浦住宿據點（示意）':id==='airport'?'金海國際機場':places.find(p=>p.id===id)?.name||id}
function routeItems(){const known=state.days[day].filter(s=>s.place&&coordinates[s.place]);const ids=known.length?known.map(x=>x.place):routeSeeds[day].filter(id=>id!=='hotel'&&id!=='airport');let route=day===0?['airport','hotel',...ids,'hotel']:day===3?['hotel',...ids,'airport']:['hotel',...ids,'hotel'];return route.filter((id,i)=>i===0||id!==route[i-1])}
function mapsUrl(a,b){return 'https://www.google.com/maps/dir/?api=1&origin='+encodeURIComponent(coordinates[a].join(','))+'&destination='+encodeURIComponent(coordinates[b].join(','))+'&travelmode=transit'}
function renderRoute(){renderNaverRoute()}
function logisticsCard(item,type,i){return `<article class="logistics-item"><div class="logistics-time">${esc(item.time)}<span>₩ ${money(item.cost)} / 人</span></div><h4>${esc(item.name)}</h4><p>${esc(item.note)}</p><div><button class="text" data-log-edit="${type}" data-index="${i}">編輯安排</button><button class="text" data-log-add="${type}" data-index="${i}">＋ 放入時間軸</button></div></article>`}
function renderLogistics(){let l=state.logistics,h=l.hotel;$('#transport-plan').innerHTML=l.transport[day].map((x,i)=>logisticsCard(x,'transport',i)).join('');$('#meal-plan').innerHTML=l.meals[day].map((x,i)=>logisticsCard(x,'meals',i)).join('');$('#hotel-name').textContent=h.name;$('#hotel-budget').textContent=`${h.nights} 晚 · ${h.rooms} 間房 · ${h.people} 人 · 每房每晚預留 ₩ ${money(h.night)}，每人住宿約 ₩ ${money(Math.round(h.night*h.rooms*h.nights/h.people))}`;const t=l.transport.flat().reduce((a,b)=>a+b.cost,0),m=l.meals.flat().reduce((a,b)=>a+b.cost,0),stay=Math.round(h.night*h.rooms*h.nights/h.people);$('#planning-budget').innerHTML=`<div><small>交通</small><strong>₩ ${money(t)}</strong></div><div><small>餐食</small><strong>₩ ${money(m)}</strong></div><div><small>住宿分攤</small><strong>₩ ${money(stay)}</strong></div><div><small>每人合計</small><strong>₩ ${money(t+m+stay)}</strong></div>`;$('#route-tabs').innerHTML=$('#day-tabs').innerHTML;if(view==='route')renderRoute()}
const originalRender=render;render=function(){originalRender();renderLogistics()};
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;let type=b.dataset.logEdit||b.dataset.logAdd;if(!type)return;let i=+b.dataset.index,item=state.logistics[type][day][i];if(b.dataset.logAdd){if(state.days[day].some(s=>s.logKey===`${type}-${day}-${i}`)){toast('這個安排已在時間軸');return}state.days[day].push({id:Date.now(),time:item.time,name:item.name,note:item.note+` · 預留 ₩ ${money(item.cost)} / 人`,cat:type==='meals'?'美食':'交通',foodId:item.foodId,logKey:`${type}-${day}-${i}`});state.days[day].sort((a,b)=>a.time.localeCompare(b.time));persist();toast('已加入今天的時間軸');return}modal(`<h2>編輯${type==='meals'?'餐食':'交通'}安排</h2><form id="log-form"><label>名稱<input name="name" required maxlength="100" value="${esc(item.name)}"></label><label>時間<input type="time" name="time" required value="${item.time}"></label><label>每人預留金額（韓元）<input type="number" name="cost" required min="0" max="99999999" value="${item.cost}"></label><label>安排與備註<textarea name="note" rows="5" maxlength="800">${esc(item.note)}</textarea></label><button class="primary">儲存安排</button></form>`);$('#log-form').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);state.logistics[type][day][i]={name:f.get('name').trim(),time:f.get('time'),cost:+f.get('cost'),note:f.get('note').trim(),foodId:item.foodId};persist();close();toast('安排已更新；已加入時間軸的項目請另外編輯')}});
$('#edit-hotel').onclick=()=>{let h=state.logistics.hotel;modal(`<h2>住宿安排</h2><form id="hotel-form"><label>住宿名稱或區域<input name="name" required maxlength="100" value="${esc(h.name)}"></label><label>每房每晚預算（韓元）<input name="night" type="number" min="1" max="99999999" required value="${h.night}"></label><label>房間數<input name="rooms" type="number" min="1" max="20" required value="${h.rooms}"></label><label>人數<input name="people" type="number" min="1" max="50" required value="${h.people}"></label><label>住宿晚數<input name="nights" type="number" min="1" max="30" required value="${h.nights}"></label><p>地圖住宿點以南浦站示意；若換住宿區域，請重新查詢各段導航。</p><button class="primary">儲存住宿計畫</button></form>`);$('#hotel-form').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);state.logistics.hotel={name:f.get('name').trim(),night:+f.get('night'),rooms:+f.get('rooms'),people:+f.get('people'),nights:+f.get('nights')};persist();close();toast('住宿與預算已更新')}};
renderLogistics();
